{
  "name": "@bandonker/opencode-plan",
  "version": "1.2.1",
  "description": "Register a /plan command that guides the agent through a thorough planning phase: research the task, ask clarifying questions, present a detailed plan, then execute it by spawning child sessions (free models first, paid as fallback).",
  "type": "module",
  "license": "MIT",
  "main": "./index.js",
  "exports": {
    ".": "./index.js",
    "./server": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plan",
    "planning",
    "research",
    "orchestration"
  ],
  "homepage": "https://github.com/Bandonker/open-toolbox",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Bandonker/open-toolbox.git"
  },
  "bugs": "https://github.com/Bandonker/open-toolbox/issues",
  "engines": {
    "node": ">=20"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.11"
  },
  "dependencies": {
    "zod": "4.1.8"
  }
}
